def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    if not h:
        return out
    # Each 5 in the bottom row sends an upward beam. The beam adopts the
    # color of each nonzero cell it encounters, filling only empty cells.
    for c, seed in enumerate(grid[-1]):
        if seed != 5:
            continue
        color = 5
        for r in range(h - 1, -1, -1):
            if grid[r][c] != 0:
                color = grid[r][c]
            else:
                out[r][c] = color
    return out
